using System;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class TransmissionHousing {
  

  public static void Base(Result r,CadAssembly a){var p=r.P;   var bounds=a.Bounds();double z=bounds[4]-p.ModelGap-p.Wall,x0=bounds[0]-p.Wall,x1=bounds[1]+p.Wall,y0=bounds[2]-p.Wall,y1=bounds[3]+p.Wall;var boltHoles=new List<CadLoop>();foreach(double x in new[]{x0+p.Wall*1.5,x1-p.Wall*1.5})foreach(double y in new[]{y0+p.Wall*1.5,y1-p.Wall*1.5})boltHoles.Add(CadLoop.Round(x,y,p.ModelBolt/2+p.Clearance));TransmissionGeometry.Solid(a,"H_BASE","Монтажное основание · отдельная деталь","housing",TransmissionGeometry.Case,TransmissionGeometry.Rect(x0,y0,x1,y1),z,p.Wall,boltHoles);
   // Four removable side walls avoid pretending an uncut box can accommodate orthogonal shafts.
   double wallTop=bounds[5]+p.ModelGap;for(int side=0;side<2;side++){double yy=side==0?y0:y1-p.Wall;TransmissionGeometry.Solid(a,"H_RIB"+side,"Продольное ребро основания","housing",TransmissionGeometry.Case,TransmissionGeometry.Rect(x0,yy,x1,yy+p.Wall),z+p.Wall,Math.Max(p.Wall,(wallTop-z)*.12));}
   foreach(var block in a.Parts.Where(q=>q.Id.StartsWith("H_BLOCK_")&&!q.Id.EndsWith("_FOOT")).ToArray()){var temp=new CadAssembly();temp.Parts.Add(block);var bb=temp.Bounds();double x=(bb[0]+bb[1])/2,y=(bb[2]+bb[3])/2,wx=Math.Max(1,Math.Min(p.Wall,(bb[1]-bb[0])*.45)),wy=Math.Max(1,Math.Min(p.Wall,(bb[3]-bb[2])*.45)),bottom=z+p.Wall,top=bb[4]+.1;if(top>bottom)TransmissionGeometry.Solid(a,block.Id+"_FOOT","Стойка опоры к основанию","housing",TransmissionGeometry.Case,TransmissionGeometry.Rect(x-wx,y-wy,x+wx,y+wy),bottom,top-bottom);}
}
  public static void Motor(Result r,CadAssembly a,Matrix3D frame,double front){var p=r.P;if(p.MotorFrame<=0||p.MotorLength<=0)return;double side=p.MotorFrame/2+2,plate=Math.Max(3,p.Wall);var holes=new List<CadLoop>{C(Math.Max(p.MotorPilot/2+p.Clearance,p.Shaft/2+1))};if(p.MotorMount>0)foreach(int x in new[]{-1,1})foreach(int y in new[]{-1,1})holes.Add(CadLoop.Round(x*p.MotorMount/2,y*p.MotorMount/2,p.MotorHole/2+p.Clearance));TransmissionGeometry.Solid(a,"H_MOTOR_PLATE","Моторная плита с буртом и четырьмя креплениями","housing",TransmissionGeometry.Case,TransmissionGeometry.Rect(-side,-side,side,side),front-plate,plate,holes,frame);var motor=TransmissionGeometry.Solid(a,"MOTOR_REFERENCE","Мотор · монтажный габарит","reference",Color.FromArgb(77,88,103),TransmissionGeometry.Rect(-p.MotorFrame/2,-p.MotorFrame/2,p.MotorFrame/2,p.MotorFrame/2),front-plate-p.MotorLength,p.MotorLength,new[]{C(p.Shaft/2)},frame);motor.Reference=true;}
  static CadLoop C(double r){return CadLoop.Round(0,0,r);}
  public static void Bearings(Result r,CadAssembly a,Matrix3D frame,double lo,double hi,double shaft,string id){double w=Math.Max(3,r.P.ModelInputBearingB),od=Math.Max(shaft+8,r.P.ModelInputBearingD);for(int j=0;j<2;j++)TransmissionGeometry.Solid(a,"H_BEARING_"+id+j,"Опора "+id+" · габарит d/D/B","bearing",TransmissionGeometry.Steel,C(od/2),j==0?lo:hi-w,w,new[]{C(shaft/2)},frame);r.Notes.Add("Опоры "+id+": d="+Engine.F(shaft)+", D="+Engine.F(od)+", B="+Engine.F(w)+" мм. Марка и посадки не выбраны. Радиальная реакция требует действительных расстояний/опор и нагрузки от соединения.");}
  public static void Add(Result r,CadAssembly a,Matrix3D input,Matrix3D output,double ilo,double ihi,double olo,double ohi){var p=r.P;Bearings(r,a,input,ilo,ihi,p.Shaft,"IN");Bearings(r,a,output,olo,ohi,p.OutputShaft,"OUT");
   // An open, serviceable bolted cradle. Bearing blocks are split and coaxial with each actual shaft frame.
   Action<Matrix3D,double,double,double,string> mounts=(frame,lo,hi,shaft,id)=>{double od=Math.Max(shaft+8,p.ModelInputBearingD),w=Math.Max(3,p.ModelInputBearingB),b=od/2+p.Wall,bolt=Math.Min(p.ModelBolt,Math.Max(1,p.Wall*.5));for(int j=0;j<2;j++){double zz=j==0?lo:hi-w;var outer=TransmissionGeometry.Rect(-b-p.Wall,-b,b+p.Wall,b);var holes=new List<CadLoop>{C(od/2+p.Clearance)};foreach(int s in new[]{-1,1})holes.Add(CadLoop.Round(s*(b+p.Wall*.4),0,bolt/2+p.Clearance));TransmissionGeometry.Solid(a,"H_BLOCK_"+id+j,"Отдельная опора "+id+" "+(j+1),"housing",TransmissionGeometry.Case,outer,zz,w,holes,frame);foreach(int s in new[]{-1,1})TransmissionGeometry.Solid(a,"H_BOLT_"+id+j+s,"Стяжка опоры · без резьбы","fastener",TransmissionGeometry.Steel,C(bolt/2),zz-2,w+4,null,RobotMath.Translation(s*(b+p.Wall*.4),0,0)*frame);}};mounts(input,ilo,ihi,p.Shaft,"IN");mounts(output,olo,ohi,p.OutputShaft,"OUT");
   if(p.UseUniversalBase)Base(r,a);
   a.Notes.Add("Корпус: обслуживаемое открытое основание, отдельные опоры/рёбра и крепёж. Замкнутый герметичный кожух, каналы смазки и оптимизация жёсткости не выполнены. Отверстия имеют заданный диаметральный зазор 2c; FDM-усадку проверять пробой.");
  }
 }
}
